// Luận Tử Vi Nam Phái (sách "Mệnh Lý Thiên Cơ"): các hàm sinh khóa. File do công cụ sinh (scripts/phu17), không sửa tay.

// TCC-HELP-BEGIN
function tccOb() {
    let d = {};
    try {
        d = JSON.parse(localStorage.getItem('laso_data')) || {};
    } catch (e) { d = {}; }
    return d.lasoOb || [];
}
function tccIdx(ob, anc) {
    let i = 0;
    for (let k = 0; k < ob.length; k++) { if (ob[k].tenCung === anc) { i = k; } }
    return i;
}
function tccCoSao(c, ten) {
    let co = false;
    if (c && Array.isArray(c.sao)) {
        for (let b = 0; b < c.sao.length; b++) { if (c.sao[b].ten === ten) { co = true; } }
    }
    return co;
}
function tccDemHoi(anc, ds, offs) {
    const ob = tccOb();
    if (ob.length < 12) return 0;
    const i = tccIdx(ob, anc);
    let dem = 0;
    for (let a = 0; a < ds.length; a++) {
        let thay = false;
        for (let o = 0; o < offs.length; o++) { if (tccCoSao(ob[(i + offs[o]) % 12], ds[a])) { thay = true; } }
        if (thay) dem++;
    }
    return dem;
}
function tccHoiChi(anc, sao, dsChi, offs) {
    const ob = tccOb();
    if (ob.length < 12) return false;
    const i = tccIdx(ob, anc);
    let thay = false;
    for (let o = 0; o < offs.length; o++) {
        const c = ob[(i + offs[o]) % 12];
        if (tccCoSao(c, sao)) {
            for (let m = 0; m < dsChi.length; m++) { if (c.chi === dsChi[m]) { thay = true; } }
        }
    }
    return thay;
}
function tccAmHop(anc, sao) {
    const ob = tccOb();
    if (ob.length < 12) return false;
    const i = tccIdx(ob, anc);
    const hop = { "Tý": "Sửu", "Sửu": "Tý", "Dần": "Hợi", "Hợi": "Dần", "Mão": "Tuất", "Tuất": "Mão", "Thìn": "Dậu", "Dậu": "Thìn", "Tỵ": "Thân", "Thân": "Tỵ", "Ngọ": "Mùi", "Mùi": "Ngọ" };
    const chiHop = hop[ob[i].chi];
    let thay = false;
    for (let k = 0; k < 12; k++) { if (ob[k].chi === chiHop && tccCoSao(ob[k], sao)) { thay = true; } }
    return thay;
}
function tccGiap(anc, s1, s2) {
    const ob = tccOb();
    if (ob.length < 12) return false;
    const i = tccIdx(ob, anc);
    const a = ob[(i + 1) % 12];
    const b = ob[(i + 11) % 12];
    return (tccCoSao(a, s1) && tccCoSao(b, s2)) || (tccCoSao(a, s2) && tccCoSao(b, s1));
}
// TCC-HELP-END

// CACH22-BEGIN
function tc22Ob() {
    let d = {};
    try {
        d = JSON.parse(localStorage.getItem('laso_data')) || {};
    } catch (e) { d = {}; }
    const ob = d.lasoOb || [];
    return ob;
}
function tc22IdxMenh(ob) {
    let i = 0;
    for (let k = 0; k < ob.length; k++) { if (ob[k].tenCung === "Mệnh") { i = k; } }
    return i;
}
function tc22CoSao(c, ten) {
    let co = false;
    if (c && Array.isArray(c.sao)) {
        for (let b = 0; b < c.sao.length; b++) { if (c.sao[b].ten === ten) { co = true; } }
    }
    return co;
}
function tc22DemHoi(ds, offs) {
    const ob = tc22Ob();
    if (ob.length < 12) return 0;
    const i = tc22IdxMenh(ob);
    let dem = 0;
    for (let a = 0; a < ds.length; a++) {
        let thay = false;
        for (let o = 0; o < offs.length; o++) { if (tc22CoSao(ob[(i + offs[o]) % 12], ds[a])) { thay = true; } }
        if (thay) dem++;
    }
    return dem;
}
function tc22HoiChi(sao, dsChi, offs) {
    const ob = tc22Ob();
    if (ob.length < 12) return false;
    const i = tc22IdxMenh(ob);
    let thay = false;
    for (let o = 0; o < offs.length; o++) {
        const c = ob[(i + offs[o]) % 12];
        if (tc22CoSao(c, sao)) {
            for (let m = 0; m < dsChi.length; m++) { if (c.chi === dsChi[m]) { thay = true; } }
        }
    }
    return thay;
}
function tc22AmHop(sao) {
    const ob = tc22Ob();
    if (ob.length < 12) return false;
    const i = tc22IdxMenh(ob);
    const cs = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];
    const hop = ["Sửu", "Tý", "Hợi", "Tuất", "Dậu", "Thân", "Mùi", "Ngọ", "Tỵ", "Thìn", "Mão", "Dần"];
    let chiHop = "";
    for (let m = 0; m < 12; m++) { if (cs[m] === ob[i].chi) { chiHop = hop[m]; } }
    let thay = false;
    for (let k = 0; k < 12; k++) { if (ob[k].chi === chiHop && tc22CoSao(ob[k], sao)) { thay = true; } }
    return thay;
}
function tc22TamHop(ds) {
    return tc22DemHoi(ds, [0, 4, 8]) === ds.length;
}
function tc22Giap(s1, s2) {
    const ob = tc22Ob();
    if (ob.length < 12) return false;
    const i = tc22IdxMenh(ob);
    const a = ob[(i + 1) % 12];
    const b = ob[(i + 11) % 12];
    return (tc22CoSao(a, s1) && tc22CoSao(b, s2)) || (tc22CoSao(a, s2) && tc22CoSao(b, s1));
}
